<?php
declare(strict_types=1);require dirname(__DIR__).'/bootstrap.php';use App\Core\Database;use App\Services\LiveDisplaySessionService;$pdo=Database::connection();$token=trim((string)($_GET['token']??''));$session=LiveDisplaySessionService::byToken($pdo,$token);if(!$session){http_response_code(404);exit('Live Display link is invalid or disabled.');}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>BDC Live Display</title><style>html,body{margin:0;width:100%;height:100%;background:#000;overflow:hidden}iframe{width:100%;height:100%;border:0;background:#000}.holding{height:100vh;display:flex;align-items:center;justify-content:center;color:#fff;background:radial-gradient(circle,#35101a,#05070b);font:900 clamp(28px,5vw,90px) Arial;text-align:center}</style></head><body><div id="root" class="holding">BACHATA DANCE COUNCIL</div><script>const token=<?=json_encode($token)?>;let version=-1,pageTimer=null,busy=false;async function tick(){if(busy)return;busy=true;try{const r=await fetch('state.php?token='+encodeURIComponent(token)+'&_='+Date.now(),{cache:'no-store'}),s=await r.json();if(!s.ok)return;if(Number(s.state_version)!==Number(version)){version=Number(s.state_version);render(s)}}catch(e){}finally{busy=false}}function render(s){clearInterval(pageTimer);const root=document.querySelector('#root');if(s.screen_type==='holding'||!s.round_id){root.className='holding';root.innerHTML=s.event_name||'BACHATA DANCE COUNCIL';return}root.className='';const frame=document.createElement('iframe');frame.src='feed.php?token='+encodeURIComponent(token)+'&state='+encodeURIComponent(s.state_version)+'&_='+Date.now();frame.setAttribute('allow','fullscreen');root.replaceChildren(frame);if(s.auto_page&&s.total_pages>1&&['competitors','callbacks','finalists'].includes(s.screen_type)){pageTimer=setInterval(async()=>{try{await fetch('advance.php?token='+encodeURIComponent(token)+'&_='+Date.now(),{method:'POST',cache:'no-store'});await tick()}catch(e){}},Number(s.page_delay_seconds)*1000)}}tick();setInterval(tick,750);</script></body></html>